<script setup>import {computed,nextTick,ref} from 'vue';import FloatingMusic from '@/components/common/FloatingMusic.vue';import OpeningScreen from './OpeningScreen.vue';import WeddingHero from './WeddingHero.vue';import WeddingCouple from './WeddingCouple.vue';import WeddingStory from './WeddingStory.vue';import WeddingEvents from './WeddingEvents.vue';import WeddingCountdown from './WeddingCountdown.vue';import Timeline from './Timeline.vue';import WeddingGallery from './WeddingGallery.vue';import WeddingMap from './WeddingMap.vue';import WeddingGifts from './WeddingGifts.vue';import WeddingWishes from './WeddingWishes.vue';import WeddingFooter from './WeddingFooter.vue';const props=defineProps({wedding:{type:Object,required:true}}),opened=ref(false),musicRef=ref(null),preset={id:'royal-red',label:'The royal celebration',primary:'#7e1725',accent:'#d6ac56',paper:'#fff8ed',ink:'#451b22',muted:'#79595a'};const style=computed(()=>{const c=props.wedding?.theme?.Colors||props.wedding?.theme?.colors||{};return {'--primary':c.Primary||c.primary||preset.primary,'--accent':c.Accent||c.accent||preset.accent,'--paper':c.Background||c.background||preset.paper,'--ink':c.Text||c.text||preset.ink,'--muted':c.TextSecondary||c.textSecondary||preset.muted}});const music=computed(()=>{const m=props.wedding?.music||{};return {Enabled:m.Enabled??m.enabled??false,Url:m.Url||m.url||'',Title:m.Title||m.title||''}});function show(n){const s=props.wedding?.settings||props.wedding?.Settings||{};return (s['Show'+n]??s['show'+n])!==false}async function open(){opened.value=true;await nextTick();musicRef.value?.play?.()}</script><style scoped>
